+    fn read_rom(&self, addr: u16) -> u8 {
+        let a = addr as usize & 0x3FFF;
+        if addr < 0x4000 {
+            self.rom[a]
+        } else {
+            self.rom[self.romx_off + a]
+        }
+    }
+
+    fn write_rom(&mut self, addr: u16, v: u8) {
+        match addr & 0x7FFF {
+            0x0000..=0x1FFF => self.ram_enabled = v & 0x0F == 0x0A,
+            0x2000..=0x2FFF => {
